import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u15")
C = "A1-A2"

L(1, "Verbos separáveis", "opbellen, meenemen, aankomen: a partícula vai para o fim.",
  ["Usar verbos separáveis no presente"],
  vocab=[V("v-opbellen","opbellen","telefonar a","verb",note="Ik bel je morgen op."), V("v-meenemen","meenemen","levar consigo","verb",note="Ik neem een paraplu mee."),
         V("v-aankomen","aankomen","chegar","verb",note="De trein komt om acht uur aan."), V("v-uitgaan","uitgaan","sair (à noite)","verb",note="We gaan vanavond uit."),
         V("v-terugkomen","terugkomen","voltar","verb")],
  ex=[("Ik bel je morgen op.","Ligo-te amanhã."),("Neem je een jas mee?","Levas um casaco?"),("De trein komt om acht uur aan.","O comboio chega às oito."),("Wanneer kom je terug?","Quando voltas?")],
  gram=[G("g-separaveis","Verbos separáveis","Muitos verbos têm uma **partícula** (op, mee, aan, uit, terug…) que, no presente, se **separa** e vai para o **fim da frase**: opbellen → *ik **bel** je morgen **op***. No infinitivo fica junta: *ik ga je **opbellen***. O acento cai na partícula: OPbellen, MEEnemen.",
    [("Ik sta om zeven uur op.","Levanto-me às sete."),("Hij komt morgen terug.","Ele volta amanhã.")],
    "Não existe nada parecido em português: é um dos pontos mais característicos do neerlandês.")],
  review=["v-opstaan","v-uitslapen","v-meegaan","v-trein"],
  cefr=C, exs=[
    MA([("opbellen","telefonar"),("meenemen","levar"),("aankomen","chegar"),("uitgaan","sair à noite"),("terugkomen","voltar")], "Verbos separáveis.", ["v-opbellen","v-meenemen","v-aankomen","v-uitgaan","v-terugkomen"]),
    WO("Ligo-te amanhã.", ["Ik","bel","je","morgen","op"], "Partícula no fim.", ["v-opbellen"]),
    WO("O comboio chega às oito.", ["De","trein","komt","om","acht","uur","aan"], "aan no fim.", ["v-aankomen"]),
    FE(["Ik","meeneem","een","paraplu."], 1, "neem … mee", "Separável: ik neem een paraplu mee.", ["v-meenemen"]),
    TR("pt-nl","Hoje à noite saímos.", ["Vanavond gaan we uit","We gaan vanavond uit"], "uitgaan → gaan … uit.", ["v-uitgaan"]),
    TR("nl-pt","Wanneer kom je terug?", ["Quando voltas","Quando é que voltas"], "terugkomen.", ["v-terugkomen"]),
    CJ("aankomen","de bus","Hoe laat komt de bus ___?", ["aan"], "A partícula «aan» no fim.", ["v-aankomen"]),
    MC("Qual está correta?", ["*Ik neem mijn laptop mee.","Ik meeneem mijn laptop.|A partícula separa-se.","Ik neem mee mijn laptop.|A partícula vai para o fim."], "neem … mee.", ["v-meenemen"]),
    LI("Ik bel je straks op.", ["Ik bel je straks op"], "Ligo-te daqui a pouco.", "op no fim.", ["v-opbellen"]),
    FB("Neem je je paspoort ___?", ["mee"], "meenemen → neem … mee.", ["v-meenemen"], choices=["mee","op","aan"], tr="Levas o passaporte?"),
  ], diff=3, mins=6)

L(2, "Mais separáveis do dia a dia", "aandoen, uitdoen, opruimen, afwassen, boodschappen doen.",
  ["Usar separáveis de tarefas domésticas"],
  vocab=[V("v-aandoen","aandoen","ligar|acender|vestir","verb",note="het licht aandoen = acender a luz"), V("v-uitdoen","uitdoen","desligar|apagar|tirar","verb"),
         V("v-opruimen","opruimen","arrumar","verb"), V("v-afwassen","afwassen","lavar a loiça","verb"), V("v-schoonmaken","schoonmaken","limpar","verb")],
  ex=[("Doe het licht aan.","Acende a luz."),("Ik ruim mijn kamer op.","Arrumo o meu quarto."),("Wie wast er af?","Quem lava a loiça?"),("We maken het huis schoon.","Limpamos a casa.")],
  gram=[G("g-separaveis-imperativo","Separáveis no imperativo","No imperativo a partícula também vai para o fim: *Doe het licht **aan**!*, *Ruim je kamer **op**!* Com dois verbos (gaan, willen, moeten…), fica junta no infinitivo: *Ik ga mijn kamer **opruimen***.",
    [("Doe je jas uit.","Tira o casaco."),("Ik moet nog afwassen.","Ainda tenho de lavar a loiça.")])],
  review=["v-lamp","v-kamer","v-schoon","v-licht"],
  cefr=C, exs=[
    MA([("aandoen","ligar"),("uitdoen","desligar"),("opruimen","arrumar"),("afwassen","lavar a loiça"),("schoonmaken","limpar")], "Tarefas.", ["v-aandoen","v-uitdoen","v-opruimen","v-afwassen","v-schoonmaken"]),
    WO("Acende a luz.", ["Doe","het","licht","aan"], "Imperativo + partícula no fim.", ["v-aandoen"]),
    WO("Arrumo o meu quarto.", ["Ik","ruim","mijn","kamer","op"], "op no fim.", ["v-opruimen"]),
    WO("Vou limpar a casa.", ["Ik","ga","het","huis","schoonmaken"], "Com «gaan», o separável fica junto no fim.", ["v-schoonmaken"]),
    TR("nl-pt","Doe je jas uit.", ["Tira o casaco"], "uitdoen = tirar (roupa).", ["v-uitdoen"]),
    TR("pt-nl","Quem lava a loiça?", ["Wie wast er af","Wie wast af"], "afwassen → wast … af.", ["v-afwassen"]),
    FE(["Ik","ga","mijn","kamer","ruim","op."], 4, "opruimen", "Depois de «gaan» o infinitivo fica junto: opruimen.", ["v-opruimen"]),
    FB("Doe de tv ___, het is laat!", ["uit"], "uitdoen = desligar.", ["v-uitdoen"], choices=["uit","aan","op"], tr="Desliga a televisão, é tarde!"),
    LI("Ik maak de keuken schoon.", ["Ik maak de keuken schoon"], "Limpo a cozinha.", "schoon no fim.", ["v-schoonmaken"]),
    CJ("afwassen","jij","Was jij vandaag ___?", ["af"], "Partícula no fim: was jij af?", ["v-afwassen"]),
  ], diff=3, mins=6)

L(3, "Diálogo: na padaria", "Um diálogo completo do quotidiano.",
  ["Compreender e participar num diálogo de compra"],
  vocab=[V("v-bakker","bakker","padeiro|padaria","noun","de",note="naar de bakker = à padaria"), V("v-volkoren","volkoren","integral","adjective"),
         V("v-gesneden","gesneden","cortado (às fatias)","adjective"), V("v-verder-nog","verder nog iets","mais alguma coisa","expression")],
  ex=[("Een volkorenbrood, gesneden, alstublieft.","Um pão integral, às fatias, por favor."),("Verder nog iets?","Mais alguma coisa?"),("Nee, dat was het.","Não, era tudo.")],
  review=["v-brood","v-alstublieft","v-pinnen","v-willen"],
  cefr=C, exs=[
    MA([("bakker","padaria"),("volkoren","integral"),("gesneden","às fatias"),("verder nog iets?","mais alguma coisa?")], "Na padaria.", ["v-bakker","v-volkoren","v-gesneden","v-verder-nog"]),
    DL([("Padeiro","Goedemorgen, wat mag het zijn?","Bom dia, o que vai ser?"),("Cliente","")], ["*Een volkorenbrood, alstublieft.","Ik ben een brood.|Não faz sentido.","Tot ziens!|Ainda não comprou nada."], "Pedido simples.", ["v-volkoren"]),
    DL([("Padeiro","Gesneden?","Às fatias?"),("Cliente","Ja, graag.","Sim, por favor."),("Padeiro","Verder nog iets?","Mais alguma coisa?"),("Cliente","")], ["*Nee, dat was het. Kan ik pinnen?","Ja, dat was het.|«Ja» contradiz «dat was het».","Gesneden!|Repetição sem sentido."], "Nee, dat was het = não, era tudo.", ["v-verder-nog"]),
    TR("nl-pt","Verder nog iets?", ["Mais alguma coisa","Deseja mais alguma coisa"], "Pergunta típica do vendedor.", ["v-verder-nog"]),
    TR("pt-nl","Não, era tudo.", ["Nee(,) dat was het","Nee(,) dat is alles"], "Fórmula fixa.", ["v-verder-nog"]),
    LI("Wat mag het zijn?", ["Wat mag het zijn"], "O que vai ser?", "Pergunta do vendedor.", ["v-bakker"]),
    FE(["Ik","ga","naar","het","bakker."], 3, "de", "naar de bakker.", ["v-bakker"]),
    CO("dialogue","Na padaria", "Bakker: Goedemorgen! Wat mag het zijn?\nAna: Een wit brood en vier krentenbollen, alstublieft.\nBakker: Wilt u het brood gesneden?\nAna: Ja, graag.\nBakker: Verder nog iets?\nAna: Nee, dat was het.\nBakker: Dat is dan zes euro tien.",
       [("Quantos pães de passas compra?", ["*Quatro","Um","Seis"]),("Quanto paga?", ["*6,10 €","10,60 €","4 €"])],
       "krentenbol = pão doce com passas.", ["v-bakker","v-gesneden"]),
    WO("Quero o pão às fatias.", ["Ik","wil","het","brood","graag","gesneden"], "graag suaviza.", ["v-gesneden"]),
    SW("Escreva o seu pedido na padaria: um pão e mais uma coisa, e diga que é tudo.", ["Een [volkorenbrood|wit brood](,) [alstublieft|graag](.) En twee [croissants|krentenbollen](.) Dat was het"],
       ["Pedido com «alstublieft» ou «graag»","Uma quantidade","Fecha com «dat was het»"], 6, "Modelo: «Een volkorenbrood, gesneden, alstublieft. En twee croissants. Dat was het.»", ["v-verder-nog"]),
  ], diff=2, mins=6)

L(4, "Diálogo: com o vizinho", "Pedir um favor e conversar com um vizinho.",
  ["Pedir e aceitar favores com educação"],
  vocab=[V("v-lenen","lenen","emprestar|pedir emprestado","verb",note="Mag ik je boor lenen? = Podes emprestar-me o berbequim?"), V("v-pakketje","pakketje","encomenda","noun","het"),
         V("v-aannemen","aannemen","receber|aceitar","verb",note="een pakketje aannemen = receber uma encomenda"), V("v-even","even","um momento|rapidamente","particle",note="Suaviza pedidos: Kun je even helpen?")],
  ex=[("Mag ik even je ladder lenen?","Podes emprestar-me a escada um momento?"),("Kun je mijn pakketje aannemen?","Podes receber a minha encomenda?"),("Natuurlijk, geen probleem!","Claro, sem problema!")],
  gram=[G("g-even","A palavrinha «even»","**even** torna um pedido mais leve e simpático: *Kun je **even** helpen?* (podes ajudar um bocadinho?). É muito frequente e soa natural, não indica pressa.",
    [("Mag ik even langs?","Posso passar um momento?")],
    "Equivale ao nosso «um bocadinho», «se faz favor», usados para suavizar.")],
  review=["v-buurman","v-helpen","v-natuurlijk","v-probleem"],
  cefr=C, exs=[
    MA([("lenen","emprestar"),("pakketje","encomenda"),("aannemen","receber"),("even","um momento")], "Favores.", ["v-lenen","v-pakketje","v-aannemen","v-even"]),
    TR("pt-nl","Podes ajudar-me um momento?", ["Kun je (me )even helpen","Kun jij (me )even helpen","Kunt u (me )even helpen"], "even suaviza.", ["v-even","v-helpen"]),
    TR("nl-pt","Kun je mijn pakketje aannemen?", ["Podes receber a minha encomenda"], "aannemen = receber.", ["v-aannemen","v-pakketje"]),
    DL([("Vizinho","Mag ik even je ladder lenen?","Podes emprestar-me a escada?"),("Você","")], ["*Natuurlijk, geen probleem!","Nee, ik ben ladder.|Não faz sentido.","Graag gedaan!|Ainda não fez o favor."], "Aceitar o pedido.", ["v-lenen"]),
    AR("pakketje","a encomenda","het", "Diminutivo -je → het.", ["v-pakketje"]),
    FE(["Ik","aanneem","je","pakketje."], 1, "neem … aan", "Separável: ik neem je pakketje aan.", ["v-aannemen"]),
    LI("Bedankt voor je hulp!", ["Bedankt voor je hulp"], "Obrigado pela ajuda!", "hulp = ajuda.", ["v-helpen"]),
    CO("dialogue","No patamar", "Buurvrouw: Hoi Pedro! Ik ga morgen op vakantie. Kun jij mijn planten water geven?\nPedro: Natuurlijk! Hoe lang ben je weg?\nBuurvrouw: Een week. Hier is mijn sleutel.\nPedro: Prima. Fijne vakantie!",
       [("O que pede a vizinha?", ["*Que regue as plantas","Que tome conta do cão","Que lhe empreste a bicicleta"]),("Quanto tempo vai estar fora?", ["*Uma semana","Um mês","Um dia"])],
       "water geven = regar.", ["v-buurman"]),
    WO("Podes emprestar-me o teu guarda-chuva?", ["Mag","ik","je","paraplu","lenen?"], "Mag ik … lenen?", ["v-lenen","v-paraplu"]),
    FB("Kun je ___ wachten? Ik kom eraan.", ["even"], "even = um momento.", ["v-even"], choices=["even","nooit","lenen"], tr="Podes esperar um momento? Já vou."),
  ], diff=3, mins=6)

L(5, "Revisão da Secção 2", "Um dia completo no quotidiano neerlandês.",
  ["Usar o vocabulário e a gramática da Secção 2 em contexto"],
  ex=[("Ik sta om zeven uur op, doe boodschappen bij de supermarkt en kook 's avonds voor mijn vrienden.","Levanto-me às sete, faço compras no supermercado e à noite cozinho para os meus amigos.")],
  review=["v-opstaan","v-boodschappen","v-koken","v-half","v-aanbieding","v-regenen","v-graag-verb","v-meenemen","v-opbellen"],
  cefr=C, exs=[
    MC("«Om half negen» é…", ["*8h30","9h30|half negen = meia hora antes das nove.","8h00|Seria «acht uur»."], "half + hora seguinte.", ["v-half"]),
    MC("Uma camisola nova:", ["*een nieuwe trui","een nieuw trui|trui é de → -e."], "de trui → nieuwe.", ["v-nieuw"]),
    WO("Levo uma garrafa de vinho.", ["Ik","neem","een","fles","wijn","mee"], "Separável + quantidade sem «van».", ["v-meenemen","v-fles"]),
    TR("pt-nl","Está a chover; levo o guarda-chuva.", ["Het regent(,) ik neem (mijn|de) paraplu mee"], "het regent + meenemen.", ["v-regenen","v-meenemen"]),
    TR("nl-pt","Op zaterdag doe ik meestal boodschappen.", ["Ao sábado geralmente faço compras","Aos sábados faço geralmente as compras"], "Revisão.", ["v-boodschappen","v-meestal"]),
    FE(["In","de","zomer","we","gaan","vaak","naar","het","strand."], 3, "gaan we", "Inversão: in de zomer gaan we…", ["v-zomer"]),
    LI("Kun je me morgen opbellen?", ["Kun je me morgen opbellen"], "Podes ligar-me amanhã?", "Com «kunnen», o separável fica junto.", ["v-opbellen"]),
    CO("text","Um sábado em Utrecht", "Op zaterdag slaapt Sanne uit. Om elf uur gaat ze naar de markt. Ze koopt een kilo appels, een stuk kaas en verse bloemen. Het regent, maar ze heeft haar paraplu meegenomen. 's Avonds komen haar vrienden eten. Ze kookt stamppot en ze drinken samen een fles wijn. Het is heel gezellig!",
       [("O que compra a Sanne no mercado?", ["*Maçãs, queijo e flores","Pão e leite","Peixe e batatas"]),("O que cozinha à noite?", ["*Stamppot","Sopa de ervilhas","Pizza"]),("Como foi a noite?", ["*Muito agradável","Aborrecida","Cansativa"])],
       "meegenomen = levou (particípio de meenemen).", ["v-meenemen","v-gezellig","v-stamppot"]),
    MA([("Wat mag het zijn?","O que vai ser?"),("Verder nog iets?","Mais alguma coisa?"),("Ga je mee?","Vens connosco?"),("Eet smakelijk!","Bom apetite!")], "Frases da Secção 2.", ["v-verder-nog","v-meegaan","v-eet-smakelijk"]),
    SW("Escreva 4–5 frases sobre o seu sábado ideal: a que horas se levanta, o que compra, o tempo e o que faz à noite.", ["Op zaterdag sta ik om negen uur op(.) Ik ga naar de markt en ik koop fruit(.) Het is zonnig(.) 's Avonds ga ik uit"],
       ["Horas e partes do dia","Pelo menos um verbo separável com a partícula no fim","Uma frase sobre o tempo com «het»","Inversões corretas"], 15, "Compare com o modelo e reveja a lista.", ["v-opstaan"]),
  ], diff=3, mins=8)

W()
